const j=$input.first().json??{};

const pagina=j.pagina??null;
const numeroOrden=j.numero_orden??null;
const nombreFichero=j.nombre_fichero??null;
const archivoId=j.archivo_id??"catalogo_actual";

let texto="";

if(typeof j.data==="string"){
  texto=j.data;
}else if(typeof j.body==="string"){
  texto=j.body;
}else if(typeof j.text==="string"){
  texto=j.text;
}else if(typeof j.texto==="string"){
  texto=j.texto;
}else{
  texto="";
}

texto=String(texto)
  .replace(/\r/g,"\n")
  .replace(/\n{3,}/g,"\n\n")
  .replace(/[ \t]{2,}/g," ")
  .trim();

return [{
  json:{
    pagina,
    numero_orden:numeroOrden,
    nombre_fichero:nombreFichero,
    archivo_id:archivoId,
    texto,
    texto_length:texto.length
  }
}];
